mapper.select:
SELECT COUNT(*) FROM medical_dept_sub mds WHERE 1=1
AND mds.`name` LIKE CONCAT('%',#{name},'%')
AND mds.dept_id = #{deptId}

SELECT deptName, COUNT(CASE WHEN job IN ('主任医师', '副主任医师')THEN 1 END) masterDoctors, subName, COUNT(did) doctors, location, id, COUNT(CASE WHEN job NOT IN ('主任医师', '副主任医师')THEN 1 END) generalDoctors FROM( SELECT mds.id id,mds.`name` subName ,location,md.`name` deptName,d.id did,d.job FROM medical_dept_sub mds LEFT JOIN medical_dept md ON mds.dept_id = md.id LEFT JOIN medical_dept_sub_doctor mdsd ON mds.id = mdsd.dept_sub_id LEFT JOIN doctor d ON mdsd.doctor_id = d.id WHERE 1 = 1
AND mds.`name` LIKE CONCAT('%',#{name},'%')
AND mds.dept_id = #{deptId}
)AS dsd GROUP BY id LIMIT #{length} OFFSET #{start}

SELECT `name`,dept_id deptId,location
FROM medical_dept_sub mds
WHERE mds.id = #{id}

